from openpyxl import load_workbook
from pathlib import Path
source = Path('/root/nasa_budget_incomplete.xlsx')
target = Path('/root/nasa_budget_recovered.xlsx')
recovered = {
    'Budget by Directorate': {
        'K5': 19285, 'F8': 4639, 'B9': 7139,
        'E10': 6555, 'K10': 23285, 'C12': 936,
    },
    'YoY Changes (%)': {
        'D7': 21.97, 'B9': 2.27, 'F9': -0.08,
    },
    'Directorate Shares (%)': {
        'F5': 26.08, 'B10': 31.35,
    },
    'Growth Analysis': {
        'E4': 8.58, 'E5': 5047, 'B7': 1534, 'B8': 7610.3,
    },
}
workbook = load_workbook(source)
for sheet_name, cells in recovered.items():
    worksheet = workbook[sheet_name]
    for coordinate, value in cells.items():
        if worksheet[coordinate].value != '???':
            raise ValueError(f'{sheet_name}!{coordinate} is not marked missing')
        worksheet[coordinate] = value
workbook.save(target)
print(target)
